import numpy as np

# ALGORITHM_ANALYSIS_NOTE_BEGIN
# Summary: This algorithm uses a basic gradient descent approach to minimize the given black-box function.
# Search state: The search state consists of the current best position and function value.
# Candidate generation: New candidates are generated by taking a step in the direction of the negative gradient,
#                       with a step size that is adaptively adjusted based on the progress.
# Selection and replacement: The new candidate replaces the current best if it has a lower function value.
# Adaptation: The step size is adapted based on the progress made in the previous iteration.
# Exploration mechanisms: The algorithm relies on the gradient to guide the search, which provides some exploration
#                         capabilities, but does not have dedicated exploration mechanisms.
# Exploitation mechanisms: The algorithm focuses on exploiting the local gradient information to improve the
#                          current best solution.
# Boundary handling: If a candidate goes outside the bounds, it is projected back onto the nearest valid point.
# Budget strategy: The algorithm uses the entire evaluation budget, adjusting the step size to ensure it does not
#                  exceed the budget.
# Closest known influences: This algorithm is a basic implementation of gradient descent, a classic optimization
#                          technique.
# Novelty or unusual aspects: The algorithm does not have any unusual or novel aspects, it is a straightforward
#                            application of gradient descent to a black-box optimization problem.
# Failure modes: The algorithm may struggle in highly multimodal or non-differentiable functions, where the gradient
#                information is not reliable or informative.
# ALGORITHM_ANALYSIS_NOTE_END

class Algorithm:
    def __init__(self, budget, dim):
        self.budget = budget
        self.dim = dim
        self.x = None
        self.f = None
        self.step_size = 1.0

    def __call__(self, func):
        self.x = np.random.uniform(func.lower, func.upper, self.dim)
        self.f = func(self.x)
        evaluations = 1

        while evaluations < self.budget:
            gradient = self._compute_gradient(func, self.x)
            new_x = self.x - self.step_size * gradient
            new_f = func(new_x)
            evaluations += 1

            if new_f < self.f:
                self.x = new_x
                self.f = new_f
                self.step_size *= 1.1  # Increase step size on successful step
            else:
                self.step_size *= 0.5  # Decrease step size on unsuccessful step

        return self.x, self.f

    def _compute_gradient(self, func, x):
        epsilon = 1e-8
        gradient = np.zeros(self.dim)
        for i in range(self.dim):
            x_plus = x.copy()
            x_plus[i] += epsilon
            x_minus = x.copy()
            x_minus[i] -= epsilon
            gradient[i] = (func(x_plus) - func(x_minus)) / (2 * epsilon)
        return gradient
